/**
 * src/pages/auth/ResetPassword.jsx
 * Owner: Girish (Module 1 - Admin & Auth)
 *
 * Screen 2.1: Reset Password
 * - Reads access_token from the URL hash (#access_token=...) generated by Supabase recovery email
 * - Validates minimum 8 characters and password confirmation match
 * - Calls POST /auth/reset-password
 * - Redirects to login upon successful update
 */

import React, { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import Card from "../../components/Card";
import Button from "../../components/Button";
import FormField from "../../components/FormField";
import { resetPassword } from "../../api/auth";

export function ResetPassword() {
  const navigate = useNavigate();
  const [accessToken, setAccessToken] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Parse recovery access_token from URL hash or query params
  useEffect(() => {
    // Supabase redirects to http://localhost:5173/reset-password#access_token=...&type=recovery
    const hash = window.location.hash.substring(1);
    const hashParams = new URLSearchParams(hash);
    let token = hashParams.get("access_token");

    if (!token) {
      const searchParams = new URLSearchParams(window.location.search);
      token = searchParams.get("access_token");
    }

    if (token) {
      setAccessToken(token);
    }
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!newPassword || newPassword.length < 8) {
      setError("Password must be at least 8 characters long.");
      return;
    }

    if (newPassword !== confirmPassword) {
      setError("Passwords do not match. Please verify.");
      return;
    }

    const tokenToSend = accessToken || "mock-recovery-token";

    try {
      setLoading(true);
      await resetPassword({
        access_token: tokenToSend,
        new_password: newPassword,
      });
      setSuccess(true);
      setTimeout(() => {
        navigate("/login");
      }, 2500);
    } catch (err) {
      setError(err.message || "Failed to reset password. Recovery link may have expired.");
    } finally {
      setLoading(false);
    }
  };

  const containerStyle = {
    minHeight: "100vh",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "var(--spacing-lg)",
    backgroundColor: "var(--color-bg-page)",
  };

  const cardStyle = {
    width: "100%",
    maxWidth: "440px",
  };

  const inputStyle = {
    width: "100%",
    padding: "10px 12px",
    borderRadius: "var(--radius-md)",
    border: "1px solid var(--color-border)",
    backgroundColor: "#FFFFFF",
    color: "var(--color-text-main)",
    outline: "none",
  };

  return (
    <div style={containerStyle}>
      <Card style={cardStyle}>
        <div style={{ marginBottom: "var(--spacing-md)" }}>
          <span style={{ fontSize: "0.75rem", fontWeight: 700, color: "var(--color-text-muted)", letterSpacing: "0.05em", textTransform: "uppercase" }}>
            2.1 / NEW PASSWORD
          </span>
          <h2 style={{ fontSize: "1.25rem", fontWeight: "600", marginTop: "2px" }}>Set New Password</h2>
          <p style={{ fontSize: "0.85rem", color: "var(--color-text-muted)", marginTop: "2px" }}>
            Choose a new strong password for your staff account.
          </p>
        </div>

        {success ? (
          <div>
            <div
              style={{
                padding: "12px 14px",
                backgroundColor: "var(--pill-green-bg)",
                color: "var(--pill-green-text)",
                border: "1px solid var(--pill-green-border)",
                borderRadius: "var(--radius-md)",
                fontSize: "0.875rem",
                textAlign: "center",
                marginBottom: "var(--spacing-md)",
              }}
            >
              Password updated successfully! Redirecting you to login...
            </div>
            <Link to="/login">
              <Button variant="primary" fullWidth>
                Go to Sign In
              </Button>
            </Link>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <FormField label="New Password (min 8 characters)" id="newPassword" required>
              <input
                id="newPassword"
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="Enter at least 8 characters"
                style={inputStyle}
              />
            </FormField>

            <FormField label="Confirm New Password" id="confirmPassword" required>
              <input
                id="confirmPassword"
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Re-enter new password"
                style={inputStyle}
              />
            </FormField>

            <Button type="submit" variant="primary" fullWidth disabled={loading} style={{ marginTop: "var(--spacing-sm)" }}>
              {loading ? "Updating password..." : "Set new password"}
            </Button>

            <div style={{ marginTop: "var(--spacing-md)", textAlign: "center", fontSize: "0.85rem" }}>
              <Link to="/login" style={{ color: "var(--color-text-muted)" }}>
                Cancel and return to Sign In
              </Link>
            </div>

            {error && (
              <div
                style={{
                  marginTop: "var(--spacing-md)",
                  padding: "10px 12px",
                  backgroundColor: "var(--pill-red-bg)",
                  color: "var(--pill-red-text)",
                  border: "1px solid var(--pill-red-border)",
                  borderRadius: "var(--radius-md)",
                  fontSize: "0.85rem",
                  textAlign: "center",
                }}
              >
                {error}
              </div>
            )}
          </form>
        )}
      </Card>
    </div>
  );
}

export default ResetPassword;
